from pathlib import Path
import tarfile,hashlib,json
records={}
for app,marker in [('customer','customer-picker'),('customer-service','Triage')]:
 archive=Path('.sites/deploy04-artifacts')/(app+'.tar.gz')
 with tarfile.open(archive) as tar:
  names=tar.getnames()
  assert not any('/.env' in n or '/.git/' in n or '/apps/api/' in n for n in names)
  hits={text:[] for text in [marker,'https://variety-configuration-applications-refine.trycloudflare.com/']}
  for item in tar.getmembers():
   if item.isfile() and item.name.endswith(('.html','.js')):
    body=tar.extractfile(item).read().decode()
    for text in hits:
     if text in body: hits[text].append(item.name)
  assert all(hits.values()),hits
 records[app]={'archive':str(archive),'sha256':hashlib.sha256(archive.read_bytes()).hexdigest(),'marker':marker,'matches':hits}
print(json.dumps(records,indent=2))
Path('.sites/deploy04-artifacts/validation.json').write_text(json.dumps(records,indent=2)+'\n')
PY"}
